SET NAMES utf8mb4;
UPDATE `page_configs` SET `config_json` = JSON_MERGE_PATCH(`config_json`, '{\"comercial_title_line1\":\"Conheça nossos\",\"comercial_sections\":[{\"id\":\"prod-sementes-1\",\"type\":\"text_image\",\"nav_label\":\"Sementes\",\"eyebrow\":\"Venda de sementes\",\"title\":\"Sementes SIF | Deforsa\",\"image\":\"uploads/pages/produtos/slides/sementes-dossel-eucalipto.webp\",\"image_side\":\"right\",\"content\":\"<h3>Seu programa de melhoramento pode ir além!</h3><p>Nossas sementes, resultado da parceria SIF e Deforsa, são originárias da Guatemala (América Central). Foram coletadas de matrizes-elite, selecionadas com critérios rigorosos de volume, tolerância a doenças e pragas, e adaptabilidade a diversas condições climáticas.</p><p>Com 368 progênies de 6 espécies estratégicas, a parceria SIF &amp; Deforsa amplia a variabilidade genética e fortalece o potencial de ganhos reais em produtividade, adaptação e qualidade no campo.</p><p>Traga variabilidade genética para o seu programa de melhoramento genético com sementes SIF.</p>\"},{\"id\":\"prod-sementes-2\",\"type\":\"cards\",\"title\":\"Por que escolher as Sementes SIF\",\"items\":[{\"title\":\"Variabilidade genética\",\"subtitle\":\"368 progênies de 6 espécies\",\"text\":\"Acesso a sementes de novas progênies e de 6 espécies estratégicas para ampliar a base genética do seu programa.\"},{\"title\":\"Materiais exclusivos\",\"subtitle\":\"Parceria com a Deforsa\",\"text\":\"Acesso a materiais genéticos estratégicos e exclusivos e ao programa de melhoramento robusto da empresa Deforsa.\"},{\"title\":\"Alta qualidade\",\"subtitle\":\"Beneficiamento e germinação\",\"text\":\"Alto grau de beneficiamento e qualidade, com alta taxa de germinação.\"},{\"title\":\"Armazenamento\",\"subtitle\":\"Laboratório de Sementes da UFV\",\"text\":\"As sementes ficam armazenadas em câmara fria no Laboratório de Sementes da UFV.\"},{\"title\":\"Logística rápida\",\"subtitle\":\"Envio em 24 horas\",\"text\":\"Processamento e envio das sementes em 24 horas, com logística rápida e eficiente.\"},{\"title\":\"Banco de dados\",\"subtitle\":\"Informações climáticas e genéticas\",\"text\":\"Banco de dados com as informações climáticas e genéticas dos materiais.\"}]},{\"id\":\"prod-sementes-3\",\"type\":\"editor\",\"title\":\"Espécies e progênies\",\"content\":\"<p>As sementes, originárias da Guatemala (América Central), estão divididas em 6 espécies, totalizando 368 progênies:</p><div class=\\\"sif-table-wrap\\\" contenteditable=\\\"false\\\"><table class=\\\"sif-table\\\"><thead><tr><th>Espécies</th><th>Progênies</th></tr></thead><tbody><tr><td>E. urophylla</td><td>168</td></tr><tr><td>E. camaldulensis</td><td>134</td></tr><tr><td>E. grandis</td><td>53</td></tr><tr><td>E. robusta</td><td>6</td></tr><tr><td>E. pellita</td><td>6</td></tr><tr><td>C. torelliana</td><td>1</td></tr></tbody><tfoot><tr><td>6</td><td>368</td></tr></tfoot></table></div>\"},{\"id\":\"prod-sementes-4\",\"type\":\"tabs\",\"title\":\"Dados climáticos dos locais de coleta\",\"tabs\":[{\"title\":\"Zacapa\",\"content\":\"<p><strong>Zacapa · Finca los Cocos</strong> · altitude 120 m</p><div class=\\\"sif-table-wrap\\\" contenteditable=\\\"false\\\"><table class=\\\"sif-table\\\"><thead><tr><th>Mês</th><th>Jan</th><th>Fev</th><th>Mar</th><th>Abr</th><th>Mai</th><th>Jun</th><th>Jul</th><th>Ago</th><th>Set</th><th>Out</th><th>Nov</th><th>Dez</th><th>Anual</th></tr></thead><tbody><tr><td>Temp. máx. (°C)</td><td>30,9</td><td>32,6</td><td>35,3</td><td>36</td><td>35,5</td><td>35,5</td><td>32,7</td><td>33,4</td><td>32,9</td><td>31,9</td><td>31,3</td><td>30,5</td><td>33,2</td></tr><tr><td>Temp. média (°C)</td><td>25</td><td>26,2</td><td>28,3</td><td>29,2</td><td>29,1</td><td>27,7</td><td>27,1</td><td>27,4</td><td>27,2</td><td>26,5</td><td>25,9</td><td>25,2</td><td>27,1</td></tr><tr><td>Temp. mín. (°C)</td><td>19,2</td><td>19,9</td><td>21,3</td><td>22,4</td><td>22,7</td><td>21,9</td><td>21,6</td><td>21,5</td><td>21,6</td><td>21,2</td><td>20,5</td><td>19,9</t