><td>22,3</td><td>23,5</td></tr><tr><td>Temp. média (°C)</td><td>16,6</td><td>17,2</td><td>18,3</td><td>19,1</td><td>19,5</td><td>19,4</td><td>19</td><td>19</td><td>18,7</td><td>18,3</td><td>17,7</td><td>16,8</td><td>18,3</td></tr><tr><td>Temp. mín. (°C)</td><td>10,8</td><td>11,1</td><td>11,9</td><td>13,3</td><td>14,3</td><td>15,3</td><td>14,6</td><td>14,3</td><td>14,4</td><td>13,9</td><td>12,7</td><td>11,3</td><td>13,2</td></tr><tr><td>Precipitação (mm)</td><td>1</td><td>3</td><td>4</td><td>25</td><td>118</td><td>231</td><td>170</td><td>141</td><td>220</td><td>131</td><td>16</td><td>5</td><td>1065</td></tr></tbody></table></div>\"},{\"title\":\"Pastores\",\"content\":\"<p><strong>Pastores · Finca Siguampar</strong> · altitude 1.800 m</p><div class=\\\"sif-table-wrap\\\" contenteditable=\\\"false\\\"><table class=\\\"sif-table\\\"><thead><tr><th>Mês</th><th>Jan</th><th>Fev</th><th>Mar</th><th>Abr</th><th>Mai</th><th>Jun</th><th>Jul</th><th>Ago</th><th>Set</th><th>Out</th><th>Nov</th><th>Dez</th><th>Anual</th></tr></thead><tbody><tr><td>Temp. máx. (°C)</td><td>22</td><td>23</td><td>24</td><td>25</td><td>24</td><td>23</td><td>23</td><td>23</td><td>22</td><td>22</td><td>22</td><td>22</td><td>22,9</td></tr><tr><td>Temp. média (°C)</td><td>16</td><td>16</td><td>18</td><td>19</td><td>19</td><td>18</td><td>18</td><td>18</td><td>18</td><td>17</td><td>16</td><td>16</td><td>17,4</td></tr><tr><td>Temp. mín. (°C)</td><td>11</td><td>11</td><td>12</td><td>14</td><td>15</td><td>15</td><td>14</td><td>15</td><td>15</td><td>14</td><td>13</td><td>12</td><td>13,4</td></tr><tr><td>Precipitação (mm)</td><td>2,7</td><td>2,8</td><td>8,3</td><td>29,9</td><td>99,2</td><td>178,2</td><td>146,9</td><td>158,8</td><td>185,6</td><td>126,9</td><td>39,6</td><td>7,1</td><td>986</td></tr></tbody></table></div>\"},{\"title\":\"Pueblos Nuevos Viña\",\"content\":\"<p><strong>Pueblos Nuevos Viña · Finca Nueva Jerusalen</strong> · altitude 1.270 m</p><div class=\\\"sif-table-wrap\\\" contenteditable=\\\"false\\\"><table class=\\\"sif-table\\\"><thead><tr><th>Mês</th><th>Jan</th><th>Fev</th><th>Mar</th><th>Abr</th><th>Mai</th><th>Jun</th><th>Jul</th><th>Ago</th><th>Set</th><th>Out</th><th>Nov</th><th>Dez</th><th>Anual</th></tr></thead><tbody><tr><td>Temp. máx. (°C)</td><td>28,5</td><td>29</td><td>30</td><td>30,1</td><td>29,6</td><td>28,4</td><td>29,2</td><td>29</td><td>28</td><td>28,4</td><td>28,1</td><td>28,1</td><td>28,9</td></tr><tr><td>Temp. média (°C)</td><td>22,6</td><td>23,1</td><td>24</td><td>24,7</td><td>24,6</td><td>24,1</td><td>24,5</td><td>24,3</td><td>23,7</td><td>23,7</td><td>22,9</td><td>22,6</td><td>23,7</td></tr><tr><td>Temp. mín. (°C)</td><td>16,8</td><td>17,2</td><td>18,1</td><td>19,3</td><td>19,7</td><td>19,8</td><td>19,8</td><td>19,6</td><td>19,5</td><td>19</td><td>17,8</td><td>17,1</td><td>18,6</td></tr><tr><td>Precipitação (mm)</td><td>2</td><td>3</td><td>11</td><td>48</td><td>189</td><td>300</td><td>232</td><td>218</td><td>284</td><td>190</td><td>36</td><td>8</td><td>1521</td></tr></tbody></table></div>\"}]},{\"id\":\"prod-sementes-5\",\"type\":\"stats\",\"title\":\"Valor comercial\",\"items\":[{\"value\":\"$100\",\"label\":\"por 5 g de sementes Deforsa\"},{\"value\":\"300\",\"label\":\"mudas, em média, com 5 g\"},{\"value\":\"< 5 g\",\"label\":\"também comercializamos quantidades inferiores a 5 g\"}]},{\"id\":\"prod-sementes-6\",\"type\":\"logos\",\"title\":\"Empresas que já adquiriram nossas sementes\",\"images\":[{\"url\":\"uploads/pages/produtos/slides/logo-arborgen.webp\",\"alt\":\"arborgen\"},{\"url\":\"uploads/pages/produtos/slides/logo-paracel.webp\",\"alt\":\"paracel\"},{\"url\":\"uploads/pages/produtos/slides/logo-suzano.webp\",\"alt\":\"suzano\"},{\"url\":\"uploads/pages/produtos/slides/logo-bracell.webp\",\"alt\":\"bracell\"},{\"url\":\"uploads/pages/produtos/slides/logo-cmpc.webp\",\"alt\":\"cmpc\"},{\"url\":\"uploads/pages/produtos/slides/logo-amcel.webp\",\"alt\":\"amcel\"},{\"url\":\"uploads/pages/produtos/slides/logo-klabin.webp\",\"alt\":\"klabin\"},{\"url\":\"uploads/pages/produtos/slides/logo-eldorado.webp\",\"alt\":\"eldorado\"}]},{\"id\":\"prod-sementes-7\",\"type\":\"cta\",\"title\":\"Aumente a variabilidade genética do seu programa\",\"text\":\"Assim como essas empresas, eleve seus resultados em campo com as sementes da SIF, em parceria de exclusividade com a Deforsa. Fale com Camila Paixão, Coordenadora de Produtos e Serviços: (31) 97127-3863 · coordenacao.produtos@sif.org.br\",\"btn_label\":\"Falar pelo WhatsApp\",\"btn_link\":\"https://wa.me/5531971273863\"},{\"id\":\"prod-tubetes-8\",\"type\":\"text_image\",\"nav_label\":\"Tubetes Biodegradáveis\",\"eyebrow\":\"Inovação sustentável\",\"title\":\"Tubetes biodegradáveis Ellepot\",\"image\":\"uploads/pages/produtos/slides/ellepot-tubetes-esteira.webp\",\"image_side\":\"left\",\"content\":\"<p>A SIF desenvolveu uma parceria com a empresa Ellepot e tem em sua unidade uma máquina de produção pronta para oferecer ao seu empreendimento os benefícios das embalagens biodegradáveis e a qualidade e confiabilidade que a marca Ellepot oferece.</p><p>Nosso compromisso é oferecer uma tecnologia que vem ganhando espaço no mercado e disponibilizar qualidade na produção de mudas. <strong>Queremos ser a sua parceira na produção de mudas mais sustentáveis.</strong></p>\"},{\"id\":\"prod-tubetes-9\",\"type\":\"stats\",\"eyebrow\":\"Fonte: Ellepot®\",\"title\":\"Ellepot pelo mundo\",\"items\":[{\"value\":\"6\",\"label\":\"continentes\"},{\"value\":\"130\",\"label\":\"países\"},{\"value\":\"10 bilhões\",\"label\":\"de unidades produzidas por ano\"}]},{\"id\":\"prod-tubetes-10\",\"type\":\"highlights\",\"title\":\"Vantagens da tecnologia Ellepot\",\"items\":[{\"title\":\"Sustentabilidade\",\"text\":\"Redução de 100% do resíduo plástico e dos desperdícios.\",\"image\":\"uploads/pages/produtos/slides/ellepot-dossel-eucalipto.webp\"},{\"title\":\"Redução de custo\",\"text\":\"Redução de até 30% em mão de obra no plantio.\",\"image\":\"uploads/pages/produtos/slides/ellepot-mudas-viveiro.webp\"},{\"title\":\"Eficiência operacional\",\"text\":\"Eliminação de etapas, agilidade na produção e personalização exclusiva.\",\"image\":\"uploads/pages/produtos/slides/ellepot-tubetes-comparativo-viveiro.webp\"},{\"title\":\"Qualidade de mudas\",\"text\":\"Aumento de 25% na sobrevivência das mudas no campo e melhoria do sistema radicular.\",\"image\":\"uploads/pages/produtos/slides/ellepot-muda-na-mao.webp\"}]},{\"id\":\"prod-tubetes-11\",\"type\":\"editor\",\"title\":\"Tubete plástico x tubete Ellepot\",\"content\":\"<p>O setor florestal exige constantes inovações para alinhar alta produtividade a práticas ambientalmente corretas. Nesse cenário, a tecnologia Ellepot surge como uma resposta direta e eficiente aos desafios operacionais do viveiro ao campo, substituindo os recipientes tradicionais por uma <strong>alternativa biodegradável de alto desempenho.</strong></p><p></p><p>Desenvolvida a partir de tubetes de papel ecológico permeáveis ao ar e à água, essa solução<strong> elimina completamente a necessidade de plásticos </strong>convencionais na fase de formação das mudas. O design do sistema favorece a aeração do substrato, o que impede o enovelamento e garante um desenvolvimento radicular incomparavelmente mais saudável, robusto e uniforme.</p><p></p><p>Além dos ganhos biológicos perceptíveis na qualidade e na estrutura das plantas, a adoção do sistema reflete diretamente na eficiência operacional. A eliminação do choque de transplantio reduz perdas em campo, enquanto o ganho em agilidade no manuseio<strong> otimiza custos com mão de obra </strong>e logística.</p><p></p><p>Com rigoroso controle de qualidade, agilidade na produção e flexibilidade nas dimensões para atender diferentes culturas, a SIF disponibiliza o sistema Ellepot para o mercado. </p><h3>Entre em contato com a nossa equipe comercial para entender como aplicar essa inovação no seu projeto.</h3><div class=\\\"sif-table-wrap\\\" contenteditable=\\\"false\\\"><table class=\\\"sif-table\\\"><thead><tr><th></th><th>Tubete de plástico</th><th>Tubete Ellepot biodegradável</th></tr></thead><tbody><tr><td>Impacto ambiental</td><td>Gera resíduos plásticos persistentes (não degradáveis)</td><td>Degrada-se no solo em curto prazo, reduzindo a poluição</td></tr><tr><td>Custos operacionais</td><td>Exige retorno, desinfecção, reposição e armazenamento</td><td>Elimina custos com retorno, desinfecção, logística reversa e armazenamento</td></tr><tr><td>Eficiência no plantio</td><td>Necessidade de remoção antes do plantio</td><td>Plantio direto com o tubete</td></tr></tbody></table></div>\"},{\"id\":\"prod-tubetes-12\",\"type\":\"stats\",\"eyebrow\":\"Fonte: Ellepot®\",\"title\":\"Estudos e resultados\",\"items\":[{\"value\":\"+350%\",\"label\":\"de crescimento em raízes secundárias\"},{\"value\":\"+35%\",\"label\":\"de crescimento na altura das plantas\"},{\"value\":\"-40%\",\"label\":\"nos custos com logística\"},{\"value\":\"+40%\",\"label\":\"de rapidez nos plantios\"}]},{\"id\":\"prod-tubetes-13\",\"type\":\"cards\",\"title\":\"Personalização e exclusividade\",\"items\":[{\"title\":\"Substrato\",\"subtitle\":\"Carolina Soil\",\"text\":\"Substrato de qualidade para a formação das mudas.\"},{\"title\":\"Adubação\",\"subtitle\":\"Osmocote + Supersimples\",\"text\":\"Adubação adequada ao desenvolvimento das mudas.\"},{\"title\":\"Alturas\",\"subtitle\":\"10, 12, 20 e 24 cm\",\"text\":\"Tubetes nas alturas de 10 cm, 12 cm, 20 cm e 24 cm.\"},{\"title\":\"Diâmetros\",\"subtitle\":\"30, 35 e 50 mm\",\"text\":\"Tubetes nos diâmetros de 30 mm, 35 mm e 50 mm.\"}]},{\"id\":\"prod-tubetes-14\",\"type\":\"editor\",\"title\":\"Expanda seu negócio\",\"content\":\"<p>Valores simulados por tamanho de tubete e quantidade:</p><div class=\\\"sif-table-wrap\\\" contenteditable=\\\"false\\\"><table class=\\\"sif-table\\\"><thead><tr><th>Tamanho</th><th>2 mil unid.</th><th>5 mil unid.</th><th>10 mil unid.</th></tr></thead><tbody><tr><td>10 x 5 cm</td><td>R$ 1.720,00</td><td>R$ 4.300,00</td><td>R$ 8.600,00</td></tr><tr><td>20 x 5 cm</td><td>R$ 3.280,00</td><td>R$ 8.200,00</td><td>R$ 16.400,00</td></tr><tr><td>24 x 8 cm</td><td>R$ 9.740,00</td><td>R$ 24.350,00</td><td>R$ 48.700,00</td></tr></tbody></table></div>\"},{\"id\":\"prod-tubetes-15\",\"type\":\"cta\",\"title\":\"Leve a tecnologia Ellepot para o seu viveiro\",\"text\":\"Fale com Pedro Gabriel Almada, Representante Comercial: (31) 9 8359-1868 · comercial@sif.org.br\",\"btn_label\":\"Falar com o comercial\",\"btn_link\":\"mailto:comercial@sif.org.br\"},{\"id\":\"prod-treinamentos-16\",\"type\":\"text_image\",\"nav_label\":\"Treinamentos In Company\",\"eyebrow\":\"Capacitação\",\"title\":\"Treinamentos In Company\",\"image\":\"uploads/pages/produtos/slides/germinar-reuniao-mapas.webp\",\"image_side\":\"right\",\"content\":\"<h3><strong>A aceleração do setor florestal exige qualificações que vão muito além de treinamentos genéricos. </strong></h3><p></p><p>A Sociedade de Investigações Florestais conecta a excelência acadêmica da Universidade Federal de Viçosa diretamente às demandas operacionais e estratégicas da sua empresa. </p><p></p><p>Desenvolvemos programas de capacitação e treinamentos personalizados sob medida para o seu time, abordando desde inovação tecnológica até gestão socioambiental e processos produtivos. </p><p></p><h3>Invista na formação de alto nível com quem há mais de cinco décadas lidera a pesquisa e o desenvolvimento florestal no país. Entre em contato e leve um treinamento alinhado as necessidades da sua equipe.</h3>\"},{\"id\":\"prod-treinamentos-17\",\"type\":\"cta\",\"title\":\"Conheça os treinamentos In Company\",\"text\":\"Veja os programas disponíveis e leve um treinamento alinhado às necessidades da sua equipe.\",\"btn_label\":\"Ver treinamentos\",\"btn_link\":\"/treinamentos-in-company\"},{\"id\":\"1786987079680-de2tup\",\"type\":\"editor\",\"title\":\"\",\"content\":\"<h1 class=\\\"ql-align-center\\\">Não perca tempo, Entre em contato com a nossa equipe comercial agora mesmo!<a href=\\\"https://api.whatsapp.com/send/?phone=553184201412&amp;text&amp;type=phone_number&amp;app_absent=0\\\" rel=\\\"noopener noreferrer\\\" target=\\\"_blank\\\"><img src=\\\"/sif-novo-h7k2x9/sif-api/uploads/editor/1786986933_691a38be23247894.webp\\\"></a></h1>\"}],\"germinar_sections\":[{\"id\":\"prod-germinar-18\",\"type\":\"text_image\",\"eyebrow\":\"Programa de talentos florestais\",\"title\":\"O que é o Germinar\",\"image\":\"uploads/pages/produtos/slides/germinar-viveiro-dupla.webp\",\"image_side\":\"right\",\"content\":\"<p>O Programa Germinar é uma iniciativa estratégica ligada às associadas SIF e à UFV, atuando como ponte entre novos talentos e a indústria.</p><p>Atua facilitando a inserção de profissionais no mercado de trabalho. Além de encaminhar para vagas, oferece suporte com avaliações técnicas e comportamentais para preparar os candidatos para a transição acadêmica-corporativa.</p>\"},{\"id\":\"prod-germinar-19\",\"type\":\"text_image\",\"eyebrow\":\"Objetivo geral\",\"title\":\"Conectar novos talentos ao setor florestal brasileiro\",\"image\":\"uploads/pages/produtos/slides/germinar-equipe-floresta.webp\",\"image_side\":\"left\",\"content\":\"<p>Conectar estagiários e trainees à prática do setor privado, oferecendo a oportunidade de vivenciar a rotina das empresas, entender sua cultura organizacional e se preparar para futuras oportunidades de atuação profissional.</p>\"},{\"id\":\"germinar-obj\",\"type\":\"editor\",\"title\":\"Objetivos Específicos\",\"content\":\"<ul><li>Preparar o futuro colaborador no final da formação acadêmica</li><li>Inserir o aluno nos processos técnicos, operacionais e culturais</li><li>Promover troca de experiências entre alunos e profissionais</li><li>Identificar talentos ainda durante a formação acadêmica</li><li>Facilitar contratações por meio do estágio</li><li>Desenvolver competências interpessoais</li><li>Atrair mão de obra qualificada</li><li>Integrar pesquisa acadêmica e prática empresarial</li></ul>\"},{\"id\":\"prod-germinar-20\",\"type\":\"tabs\",\"title\":\"Benefícios\",\"tabs\":[{\"title\":\"Para a empresa\",\"content\":\"<ul><li><strong>Formação de novos talentos:</strong> oportunidade de desenvolver profissionais alinhados à cultura, aos valores e às necessidades da empresa.</li><li><strong>Renovação e inovação:</strong> entrada de jovens talentos com novas ideias, conhecimentos atualizados e diferentes perspectivas.</li><li><strong>Formação de futuros profissionais:</strong> possibilidade de identificar e preparar talentos para futuras posições estratégicas.</li><li><strong>Otimização do recrutamento:</strong> acesso a candidatos selecionados e direcionados conforme o perfil e as demandas da empresa.</li></ul>\"},{\"title\":\"Para o candidato\",\"content\":\"<ul><li><strong>Desenvolvimento profissional:</strong> oportunidade de colocar em prática os conhecimentos adquiridos na formação acadêmica.</li><li><strong>Experiência no mercado de trabalho:</strong> vivência da rotina corporativa e contato com desafios reais da profissão.</li><li><strong>Desenvolvimento de competências:</strong> aprimoramento de habilidades técnicas, comportamentais e relacionais.</li><li><strong>Possibilidade de efetivação:</strong> oportunidade de crescimento profissional e futuras contratações.</li></ul>\"},{\"title\":\"Para a SIF\",\"content\":\"<ul><li><strong>Fortalecimento de parcerias:</strong> aproximação com empresas e ampliação do relacionamento institucional, gerando conexão entre empresas, instituições de ensino e novos talentos.</li><li><strong>Valorização institucional:</strong> fortalecimento da imagem da SIF como agente de desenvolvimento profissional e de formação de talentos.</li><li><strong>Ampliação do impacto social:</strong> contribuição para a empregabilidade, a qualificação profissional e o desenvolvimento de novos talentos.</li></ul>\"}]},{\"id\":\"prod-germinar-21\",\"type\":\"stats\",\"title\":\"O programa em números\",\"items\":[{\"value\":\"6 a 24\",\"label\":\"meses de duração para o mesmo candidato\"},{\"value\":\"2\",\"label\":\"modalidades: estagiário e trainee\"},{\"value\":\"6\",\"label\":\"estados com talentos do programa\"}]},{\"id\":\"prod-germinar-22\",\"type\":\"text_image\",\"eyebrow\":\"Presença nacional\",\"title\":\"Agregando talentos ao longo do país\",\"image\":\"uploads/pages/produtos/slides/germinar-mapa-brasil.webp\",\"image_side\":\"right\",\"content\":\"<ul><li><strong>Bahia:</strong> Alagoinhas</li><li><strong>Maranhão:</strong> Imperatriz e região</li><li><strong>Minas Gerais:</strong> Capelinha, Itamarandiba e Três Marias</li><li><strong>Mato Grosso do Sul:</strong> Bataguassu e Três Lagoas</li><li><strong>Rio Grande do Sul:</strong> Guaíba</li><li><strong>São Paulo:</strong> Jacareí e Lençóis Paulista</li></ul>\"},{\"id\":\"prod-germinar-23\",\"type\":\"quote\",\"title\":\"Exportando talentos para o mundo\",\"text\":\"No Germinar, encontrei na CMPC Chile a ponte entre a pesquisa do meu doutorado e a escala operacional. Hoje lidero um projeto de otimização da micropropagação de Eucalyptus nitens e aprendi a transitar entre ciência, gestão e trabalho em outro idioma e país. É uma experiência que recomendo a quem quer ver a ciência florestal acontecer na prática.\",\"author\":\"Paloma Brás\",\"role\":\"Pesquisadora Trainee · CMPC Chile\"},{\"id\":\"prod-germinar-24\",\"type\":\"highlights\",\"title\":\"Modalidades do programa\",\"items\":[{\"title\":\"Estagiário\",\"text\":\"Vagas destinadas a estudantes que estejam cursando a graduação, com obrigatoriedade de vínculo acadêmico ativo.\",\"image\":\"uploads/pages/produtos/slides/germinar-laboratorio-estagiaria.webp\"},{\"title\":\"Trainee\",\"text\":\"Vagas destinadas a pessoas com graduação concluída, incluindo profissionais que estejam cursando ou já tenham concluído a pós-graduação.\",\"image\":\"uploads/pages/produtos/slides/germinar-trainee-floresta.webp\"},{\"title\":\"Oportunidades internacionais\",\"text\":\"O Germinar conecta talentos universitários a grandes empresas do setor florestal no exterior, promovendo experiências internacionais e o intercâmbio de conhecimentos. Um exemplo é a atuação de estudantes na CMPC, no Chile.\",\"image\":\"uploads/pages/produtos/slides/germinar-capa-floresta-eucalipto.webp\"}]},{\"id\":\"prod-germinar-25\",\"type\":\"cards\",\"title\":\"Fluxograma do programa\",\"items\":[{\"title\":\"Demanda\",\"subtitle\":\"Busca ativa ou passiva\",\"text\":\"A demanda é recebida por meio da busca ativa pelo setor comercial ou de forma passiva, pela empresa.\"},{\"title\":\"Proposta\",\"subtitle\":\"Conforme a vaga\",\"text\":\"A proposta é elaborada conforme as exigências e os requisitos da vaga solicitados pela empresa no formulário.\"},{\"title\":\"Validação\",\"subtitle\":\"Junto à empresa\",\"text\":\"A proposta é submetida à validação junto à empresa.\"},{\"title\":\"Contrato\",\"subtitle\":\"Formalização\",\"text\":\"Após a validação, a proposta é encaminhada ao setor de contratos para formalização entre as partes.\"},{\"title\":\"Faturamento\",\"subtitle\":\"Nota fiscal\",\"text\":\"Após a assinatura do contrato, o processo é direcionado ao setor de faturamento para emissão da nota fiscal.\"}]},{\"id\":\"germinar-plano\",\"tabs\":[{\"title\":\"Período & Pré-requisitos\",\"content\":\"<p>A duração do programa depende do nível acadêmico, graduação ou pós-graduação: <strong>Mínimo: 6 meses | Máximo: 24 meses.</strong></p><h3>Graduação</h3><p><strong>Pré-requisitos:</strong> Ter cursado todas as disciplinas do curso.</p><p><strong>Exceção:</strong></p><ul><li>Estágio Supervisionado (ENF 498)</li><li>Trabalho de Conclusão de Curso (ENF 497/499)</li></ul><h3>Pós-Graduação</h3><p><strong>Pré-requisitos:</strong> Ter cursado todas as disciplinas do curso.</p><p><strong>Exceção:</strong></p><ul><li>Pesquisa (ENF 799)</li><li>Seminários I e II (ENF 797)</li></ul>\"},{\"title\":\"Benefícios\",\"content\":\"<h3>Benefícios Gerais</h3><ul><li>Auxílio moradia</li><li>Auxílio alimentação</li><li>Deslocamento</li><li>Plano de Saúde</li><li>Seguro de Vida</li></ul><h3></h3>\"},{\"title\":\"Etapas do Processo Seletivo\",\"content\":\"<h3>Etapas</h3><ul><li>Análise de histórico escolar</li><li>Avaliação de currículo</li><li>Entrevista</li><li>Avaliação de perfil psicológico</li><li>Soft skills e perfil cultural</li></ul><h3>Avaliação e Acompanhamento</h3><ol><li><strong>Avaliação de Perfil:</strong> Avaliação inicial dos bolsistas com teste Disc Assessment, avaliação de personalidade, e um questionário de Soft Skills.</li><li><strong>Feedback para o Bolsista:</strong> Reunião individual com o bolsista para feedback dos resultados e levantamento dos pontos de desenvolvimento, de forma que os mesmos construam o próprio PD&amp;I.</li><li><strong>Reunião com o Gestor Responsável:</strong> Reunião de alinhamento com o Gestor Responsável pelo bolsista para definição do plano de atividades durante todo o período do estágio.</li><li><strong>Reuniões Individuais com o Bolsista:</strong> Reunião de acompanhamento do plano de atividades do bolsista, de forma a avaliar a evolução das ações, resultados e definição de novas ações quando necessário.</li><li><strong>Avaliação Final:</strong> Ao final da bolsa, o aluno passa por uma avaliação final de perfil, para traçar a evolução das soft skills trabalhadas no plano de ação.</li></ol>\"},{\"title\":\"Direitos e Deveres\",\"content\":\"<h3>Bolsista</h3><ul><li>Cumprir a carga horária de 20 ou 30 horas semanais</li><li>Manter conduta ética, respeitosa e profissional durante todo o período</li><li>Apresentar relatórios de acompanhamento, quando solicitado</li><li>Zelar pelo bom uso das instalações da empresa</li><li>Manter sigilo sobre informações confidenciais</li></ul><h3>Empresa</h3><ul><li>Designar um supervisor para acompanhamento do bolsista</li><li>Garantir as condições necessárias para a execução da atividade</li><li>Oferecer ambiente seguro e condizente com as atividades de formação</li><li>Fornecer feedback regular sobre o desempenho do bolsista</li></ul><h3>SIF</h3><ul><li>Coordenar e supervisionar o cumprimento das atividades previstas</li><li>Oferecer suporte acadêmico aos bolsistas</li><li>Zelar pela qualidade do programa e pelo cumprimento das metas pedagógicas</li></ul>\"}],\"type\":\"tabs\",\"title\":\"Plano Pedagógico \"},{\"id\":\"prod-germinar-26\",\"type\":\"tabs\",\"title\":\"Segurança, certificação e investimento\",\"tabs\":[{\"title\":\"Certificação\",\"content\":\"<p>No fim do programa, o candidato receberá um certificado de participação emitido pela SIF/UFV em parceria com a empresa envolvida.</p><p>Inovações, produtos, relatórios ou qualquer material intelectual desenvolvido durante o programa serão considerados de coautoria entre aluno, orientador e empresa, salvo acordo em contrato específico.</p>\"},{\"title\":\"Seguro e saúde\",\"content\":\"<p>Os participantes do programa devem estar cobertos por seguro contra acidentes pessoais, contratado pela SIF ou pela empresa.</p><p>Também é obrigatória a existência de plano de saúde para todos os candidatos vinculados ao programa.</p>\"},{\"title\":\"Investimento\",\"content\":\"<p>Os custos envolvem a bolsa acadêmica, alimentação, moradia, deslocamento, seguro de vida, plano de saúde, formação de RH e gestão SIF, variando conforme os objetivos e a especialidade de cada proposta.</p><ul><li>1ª parcela: 50% do valor na assinatura do contrato;</li><li>2ª parcela: 50% no início do terceiro mês.</li></ul>\"},{\"title\":\"Rescisão e cancelamento\",\"content\":\"<p>O desligamento do aluno poderá ocorrer nos seguintes casos:</p><ul><li>descumprimento das regras do programa;</li><li>abandono das atividades;</li><li>conduta inadequada ou antiética;</li><li>a pedido do candidato, mediante justificativa formal;</li><li>cancelamento do vínculo acadêmico com a universidade, no caso da modalidade estagiário.</li></ul>\"}]},{\"id\":\"prod-germinar-27\",\"type\":\"cta\",\"title\":\"Sua empresa quer contratar talentos do Programa Germinar?\",\"text\":\"O formulário busca identificar as demandas de contratação e o perfil profissional desejado por cada empresa, permitindo elaborar propostas mais assertivas e conectar os talentos do Programa Germinar às oportunidades disponíveis.\",\"btn_label\":\"Registrar a demanda da empresa\",\"btn_link\":\"https://docs.google.com/forms/d/e/1FAIpQLSdQ3ZKbQCZn_OLMnkeK4ynmQauKu8sYo1D_GT0LV_kiMn2fXA/viewform?usp=header\"}],\"cultivares_sections\":[{\"id\":\"prod-cultivares-28\",\"type\":\"editor\",\"title\":\"\",\"content\":\"<h1 class=\\\"ql-align-center\\\"><strong>Liderança e rigor técnico na proteção de cultivares do setor florestal.</strong></h1><p class=\\\"ql-align-center\\\"></p><p class=\\\"ql-align-center\\\">Com a tradição de unir a excelência acadêmica da UFV às demandas reais do mercado, a Sociedade de Investigações Florestais atua diretamente na salvaguarda de materiais genéticos estratégicos. Desde a fundamentação científica até o registro e proteção formal, garantimos a segurança jurídica e a valorização da inovação desenvolvida por nossas empresas parceiras.</p><p></p><p><img src=\\\"/sif-novo-h7k2x9/sif-api/uploads/editor/1786986505_2823588d21ee8bd5.webp\\\"></p><p></p><h2 class=\\\"ql-align-center\\\"><strong>36</strong> Empresas Atendidas</h2><p class=\\\"ql-align-center\\\"></p><h2 class=\\\"ql-align-center\\\"><strong>40</strong> Cultivares Registradas</h2><p class=\\\"ql-align-center\\\"></p><h2 class=\\\"ql-align-center\\\"><strong>25</strong> Cultivares Protegidas</h2><p class=\\\"ql-align-center\\\"></p><h2 class=\\\"ql-align-center\\\"><strong>14</strong> Cultivares do Projeto </h2><h2 class=\\\"ql-align-center\\\">Tolerância à Seca em Processo de Proteção</h2><p></p><p><img src=\\\"/sif-novo-h7k2x9/sif-api/uploads/editor/1786986556_c4e5bf8d27676301.webp\\\"></p><p></p><h3 class=\\\"ql-align-center\\\">Portfólio de Espécies e Parcerias</h3><p class=\\\"ql-align-center\\\"></p><p class=\\\"ql-align-center\\\">Nosso trabalho abrange gêneros de extrema relevância para a silvicultura nacional, como<strong> Eucalyptus, Corymbia, Pinus e Elaeis guineensis (Dendê)</strong>. O alcance dessa atuação é comprovado pela confiança das maiores corporações do setor, que contam com a SIF para proteger seus ativos biológicos.</p><p class=\\\"ql-align-center\\\"></p><p class=\\\"ql-align-center\\\"></p><p class=\\\"ql-align-center\\\"></p><p class=\\\"ql-align-center\\\"></p><h3 class=\\\"ql-align-center\\\">Projeta os ativos genéticos da sua empresa com quem é referência nacional no setor florestal. Entre em contato com a nossa coordenação de inovação e projetos.</h3>\"}],\"importacao_sections\":[{\"id\":\"prod-importacao-29\",\"type\":\"editor\",\"title\":\"\",\"content\":\"<h1 class=\\\"ql-align-center\\\"><strong>Agilidade e segurança regulatória na importação e exportação florestal</strong></h1><h3 class=\\\"ql-align-center\\\"></h3><h3 class=\\\"ql-align-center\\\">O avanço da pesquisa e do desenvolvimento tecnológico no setor florestal exige trânsito rápido e seguro de insumos biológicos. A SIF atua como ponte estratégica para viabilizar esse fluxo, garantindo que materiais genéticos e amostras cheguem ao destino com máxima eficiência operacional e conformidade legal.</h3><p></p><p><img src=\\\"/sif-novo-h7k2x9/sif-api/uploads/editor/1787080472_b17082b3b87b8492.webp\\\"></p><p></p><p class=\\\"ql-align-center\\\">Nossa atuação estratégica junto ao Ministério da Agricultura e Pecuária (MAPA) conta com um diferencial decisivo: a presença de uma unidade do próprio Ministério instalada no campus da UFV.</p><p class=\\\"ql-align-center\\\"></p><p class=\\\"ql-align-center\\\">Essa proximidade geográfica e institucional permite realizar etapas cruciais, como a inspeção e a lacração de cargas, diretamente nas dependências da universidade. Ao viabilizar o embarque direto, eliminamos intermediários desnecessários e mitigamos riscos burocráticos.</p><p class=\\\"ql-align-center\\\"></p><h2 class=\\\"ql-align-center\\\">Impacto Direto na Sua Operação</h2><p class=\\\"ql-align-center\\\">Otimize a logística internacional dos seus materiais genéticos e pesquisas. Fale com a equipe técnica da SIF e garanta embarques diretos sem complicações.</p>\"}],\"boletim_sections\":[{\"id\":\"prod-boletim-30\",\"type\":\"pdfs\",\"eyebrow\":\"Para autores\",\"title\":\"Envie seu boletim\",\"pdfs\":[{\"title\":\"Diretrizes de submissão do Boletim Técnico\",\"url\":\"uploads/pdfs/boletim-diretrizes-de-submissao.pdf\"}]}]}') WHERE `page_key` = 'produtos';
